pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    function testFuzz_property(uint8 badIndex, uint256 len) public {
        vm.assume(len > 0 && len <= 10);
        uint256 idx = uint256(badIndex) % len;

        GoodCallee good = new GoodCallee();
        Reverter bad = new Reverter();

        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            if (i == idx) tos[i] = address(bad);
            else tos[i] = address(good);
        }

        bool ok;
        try c.transfer(address(this), address(this), tos, 1) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract GoodCallee {
    fallback() external payable {}
}

contract Reverter {
    fallback() external payable {
        revert("fail");
    }
}
